<?php
declare(strict_types=1);
function linkedInPostLink(array $data):?string{$value=$data['link']??'';if(!is_string($value))fail('INVALID_INPUT','link muss ein String sein.',422);$link=trim($value);if($link==='')return null;if(strlen($link)>2048||!filter_var($link,FILTER_VALIDATE_URL))fail('INVALID_LINK','Der Link muss eine gültige absolute HTTP(S)-URL sein.',422);$scheme=strtolower((string)parse_url($link,PHP_URL_SCHEME));if(!in_array($scheme,['http','https'],true)||parse_url($link,PHP_URL_USER)!==null||parse_url($link,PHP_URL_PASS)!==null)fail('INVALID_LINK','Der Link muss eine gültige absolute HTTP(S)-URL sein.',422);return $link;}
function createStoredLinkedInPost(int $userId,array $channel,string $baseText,string $text,?string $link):array{$pdo=db();$now=date('Y-m-d H:i:s');$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO posts(base_text,resolved_text,link_url,created_by,status,created_at,updated_at) VALUES(?,?,?,?,'publishing',?,?)")->execute([$baseText,$text,$link,$userId,$now,$now]);$postId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO post_targets(post_id,provider_id,social_account_id,channel_id,final_text,final_link_url,status,created_at,updated_at) VALUES(?,'linkedin',?,?,?,?, 'publishing',?,?)")->execute([$postId,$channel['social_account_id'],$channel['id'],$text,$link,$now,$now]);$targetId=(int)$pdo->lastInsertId();$pdo->commit();return[$postId,$targetId];}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();throw $exception;}}
function finishStoredLinkedInPost(int $postId,int $targetId,string $status,?string $externalPostId,?string $errorCode,?string $errorMessage):string{$pdo=db();$now=date('Y-m-d H:i:s');$pdo->beginTransaction();try{$published=$status==='published'?$now:null;$pdo->prepare('UPDATE posts SET status=?,updated_at=? WHERE id=?')->execute([$status,$now,$postId]);$pdo->prepare('UPDATE post_targets SET status=?,external_post_id=?,published_at=?,error_code=?,error_message=?,updated_at=? WHERE id=?')->execute([$status,$externalPostId,$published,$errorCode,$errorMessage,$now,$targetId]);$pdo->commit();return $now;}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();throw $exception;}}
function recordLinkedInPublishingAttempt(int $postId,int $channelId,string $text,string $visibility,string $status,?string $externalPostId,?string $errorCode):void{db()->prepare("INSERT INTO publishing_attempts(post_id,provider_id,social_channel_id,mode,final_text,visibility,external_post_id,status,error_code,created_at) VALUES(?,'linkedin',?,'live',?,?,?,?,?,?)")->execute([$postId,$channelId,$text,$visibility,$externalPostId,$status,$errorCode,date('Y-m-d H:i:s')]);}
function linkedInPostPayload(string $author,string $text,string $visibility,?string $link):array{$payload=['author'=>$author,'commentary'=>$text,'visibility'=>$visibility,'distribution'=>['feedDistribution'=>'MAIN_FEED','targetEntities'=>[],'thirdPartyDistributionChannels'=>[]],'lifecycleState'=>'PUBLISHED','isReshareDisabledByAuthor'=>false];if($link!==null)$payload['content']=['article'=>['source'=>$link]];return $payload;}
function linkedInPostRequest(string $accessToken,array $payload):string{$headers=['Accept: application/json','Content-Type: application/json','Authorization: Bearer '.$accessToken,'X-Restli-Protocol-Version: 2.0.0','Linkedin-Version: '.LINKEDIN_API_VERSION];$body=@file_get_contents(rtrim(linkedInEndpoint('api'),'/').'/rest/posts',false,stream_context_create(['http'=>['method'=>'POST','timeout'=>10,'ignore_errors'=>true,'header'=>implode("\r\n",$headers),'content'=>json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]]));$responseHeaders=$http_response_header??[];$status=0;if(isset($responseHeaders[0])&&preg_match('#\s(\d{3})\s#',$responseHeaders[0],$match))$status=(int)$match[1];$postId=null;foreach($responseHeaders as $header)if(stripos($header,'x-restli-id:')===0){$postId=trim(substr($header,strlen('x-restli-id:')));break;}if($status===201&&is_string($postId)&&$postId!==''&&strlen($postId)<=500)return $postId;if($status===401)throw new OAuthException('LINKEDIN_POST_TOKEN','Die LinkedIn-Verbindung ist abgelaufen. Bitte erneut verbinden.',422);if($status===403)throw new OAuthException('LINKEDIN_POST_FORBIDDEN','LinkedIn erlaubt die Veröffentlichung für dieses Profil nicht.',422);if($status===429)throw new OAuthException('LINKEDIN_POST_RATE_LIMIT','LinkedIn erlaubt derzeit keine weitere Veröffentlichung. Bitte später erneut versuchen.',429);if($status===400||$status===422)throw new OAuthException('LINKEDIN_POST_VALIDATION','LinkedIn hat den Beitrag wegen ungültiger Daten abgelehnt.',422);throw new OAuthException('LINKEDIN_POST_FAILED','LinkedIn konnte den Beitrag nicht veröffentlichen.',502);}
function listPosts():never{requireAuth();$rows=db()->query("SELECT p.id,p.created_at,p.status,p.base_text,p.resolved_text,p.link_url,t.provider_id,t.final_text,t.final_link_url,t.status target_status,t.external_post_id,t.published_at,c.display_name channel_name FROM posts p LEFT JOIN post_targets t ON t.post_id=p.id LEFT JOIN social_channels c ON c.id=t.channel_id ORDER BY p.created_at DESC,p.id DESC,t.id")->fetchAll();$posts=array_map(fn(array $row)=>['id'=>(int)$row['id'],'createdAt'=>$row['created_at'],'baseText'=>$row['base_text'],'resolvedText'=>$row['resolved_text'],'linkUrl'=>$row['link_url'],'status'=>$row['target_status']??$row['status'],'providerId'=>$row['provider_id'],'channelName'=>$row['channel_name'],'finalText'=>$row['final_text'],'finalLinkUrl'=>$row['final_link_url'],'externalPostId'=>$row['external_post_id'],'publishedAt'=>$row['published_at']],$rows);ok(['posts'=>$posts]);}
function publishLinkedInTestPost():never{$user=requireAdmin();requireCsrf();$data=input();$channelId=$data['channelId']??null;$confirmed=$data['confirmed']??null;if(!is_int($channelId)||$channelId<1)fail('INVALID_INPUT','Ein gültiger LinkedIn-Zielkanal ist erforderlich.',422);if($confirmed!==true)fail('LINKEDIN_CONFIRMATION_REQUIRED','Die ausdrückliche Veröffentlichungsbestätigung fehlt.',422);$baseText=requireStringField($data,'baseText',50000,false);$text=requireStringField($data,'text',3000);$link=linkedInPostLink($data);$visibility=requireStringField($data,'visibility',20);if($text==='')fail('INVALID_INPUT','Der Beitragstext darf nicht leer sein.',422);if(!in_array($visibility,['PUBLIC','CONNECTIONS'],true))fail('INVALID_INPUT','Ungültige LinkedIn-Sichtbarkeit.',422);$stmt=db()->prepare("SELECT c.id,c.social_account_id,c.channel_type,c.status,c.can_publish,a.external_account_id,a.access_token_encrypted,a.token_expires_at,a.scopes,a.status account_status FROM social_channels c JOIN social_accounts a ON a.id=c.social_account_id WHERE c.id=? AND c.provider_id='linkedin'");$stmt->execute([$channelId]);$channel=$stmt->fetch();if(!$channel)fail('LINKEDIN_CHANNEL_NOT_FOUND','LinkedIn-Zielkanal nicht gefunden.',404);if($channel['channel_type']!=='personal')fail('LINKEDIN_PERSONAL_ONLY','Echte Testbeiträge sind derzeit nur für persönliche LinkedIn-Profile erlaubt.',422);if($channel['status']!=='active'||$channel['account_status']!=='connected')fail('LINKEDIN_NOT_CONNECTED','Das persönliche LinkedIn-Profil ist nicht verbunden.',422);if(!in_array('w_member_social',linkedInScopeList($channel['scopes']),true)||(int)$channel['can_publish']!==1)fail('LINKEDIN_MEMBER_SCOPE','Für echte LinkedIn-Beiträge fehlt die Berechtigung w_member_social.',422);if(is_string($channel['token_expires_at'])&&strtotime($channel['token_expires_at'])<=time())fail('LINKEDIN_POST_TOKEN','Die LinkedIn-Verbindung ist abgelaufen. Bitte erneut verbinden.',422);[$postId,$targetId]=createStoredLinkedInPost((int)$user['id'],$channel,$baseText,$text,$link);try{$accessToken=decryptSecret((string)$channel['access_token_encrypted']);$payload=linkedInPostPayload('urn:li:person:'.$channel['external_account_id'],$text,$visibility,$link);$externalPostId=linkedInPostRequest($accessToken,$payload);$publishedAt=finishStoredLinkedInPost($postId,$targetId,'published',$externalPostId,null,null);recordLinkedInPublishingAttempt($postId,$channelId,$text,$visibility,'success',$externalPostId,null);ok(['status'=>'success','message'=>'LinkedIn-Beitrag erfolgreich veröffentlicht.','postId'=>$externalPostId,'storedPostId'=>$postId,'publishedAt'=>date(DATE_ATOM,strtotime($publishedAt)),'channelId'=>$channelId]);}catch(OAuthException $exception){finishStoredLinkedInPost($postId,$targetId,'failed',null,$exception->errorCode,$exception->getMessage());recordLinkedInPublishingAttempt($postId,$channelId,$text,$visibility,'failed',null,$exception->errorCode);throw $exception;}catch(CryptoException){$code='LINKEDIN_POST_TOKEN';$message='Die LinkedIn-Verbindung ist ungültig. Bitte erneut verbinden.';finishStoredLinkedInPost($postId,$targetId,'failed',null,$code,$message);recordLinkedInPublishingAttempt($postId,$channelId,$text,$visibility,'failed',null,$code);throw new OAuthException($code,$message,422);}}
